import os
import torch


class Config:
    # ==========================================
    # Paths & Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_3")
    SUBMISSION_DIR = "./submission"

    # Ensure working directories exist
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # Metadata Files (Generated by the provided script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Raw Metadata (For Taxonomy Info)
    TRAIN_META_JSON = os.path.join(INPUT_DIR, "train_metadata.json")

    # Output Files
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model_idea3.pth")

    # ==========================================
    # Data Parameters
    # ==========================================
    SEED = 42
    NUM_CLASSES = 15501  # Total species
    IMAGE_SIZE = 380  # Native resolution for EfficientNet-B4
    NUM_WORKERS = 12  # Based on 12 vCPUs

    # Sampling Strategy
    # "sqrt" for square-root sampling (balanced), "instance" for standard random
    SAMPLING_STRATEGY = "sqrt"

    # ==========================================
    # Model Parameters
    # ==========================================
    # Backbone
    MODEL_NAME = "tf_efficientnet_b4_ns"  # timm implementation, noisy student weights
    PRETRAINED = True
    DROP_RATE = 0.3
    DROP_PATH_RATE = 0.2

    # Embedding Head
    EMBEDDING_DIM = 512  # Projection dimension before ArcFace

    # ArcFace Parameters
    ARCFACE_SCALE = 30.0
    ARCFACE_MARGIN = 0.50

    # Auxiliary Heads (Taxonomic Regularization)
    USE_AUX_HEADS = True
    # These will be populated dynamically after loading taxonomy mapping
    # but we define the weights here.
    LOSS_WEIGHT_SPECIES = 1.0
    LOSS_WEIGHT_GENUS = 0.5
    LOSS_WEIGHT_FAMILY = 0.5

    # ==========================================
    # Training Parameters
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # High throughput settings for A100
    # B4 is heavy. Batch size 32-64 per step is reasonable.
    # We aim for effective batch size of 128 via accumulation if needed.
    BATCH_SIZE = 32
    GRAD_ACCUM_STEPS = 4  # 32 * 4 = 128 effective batch size

    NUM_EPOCHS = 30

    # Optimization
    LEARNING_RATE = 1e-4  # Lower LR for fine-tuning unfrozen backbone
    WEIGHT_DECAY = 1e-4
    MAX_GRAD_NORM = 10.0

    # Scheduler (Cosine Annealing)
    SCHEDULER_T_MAX = NUM_EPOCHS
    SCHEDULER_MIN_LR = 1e-6

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 5

    # Debugging
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SAMPLE_SIZE = 1000

    @classmethod
    def print_config(cls):
        print("=" * 30)
        print("CONFIG")
        print("=" * 30)
        for k, v in cls.__dict__.items():
            if not k.startswith("__") and not callable(v):
                print(f"{k}: {v}")
        print("=" * 30)
